<?php /** @var \Sysfera\Plugin $sf @var string $tab @var array $whs @var array $staff @var array $users @var array $devices */
include __DIR__ . '/_nav.php'; ?>
<div class="page-h"><h1><?= e($sf->t('nav_warehouses')) ?></h1></div>
<div class="card"><h3><?= e($sf->t('pickup_whs')) ?></h3>
  <?php foreach ($whs as $w): ?><form method="post" class="row"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$w['id'] ?>"><b><?= e($w['name']) ?></b> <code><?= e($w['code']) ?></code> <span class="muted"><?= e($sf->t($w['active'] ? 'active' : 'inactive')) ?></span><button class="btn sm" name="do" value="toggle_wh"><?= e($sf->t($w['active'] ? 'deactivate' : 'activate')) ?></button></form><?php endforeach; ?>
  <form method="post" class="row"><?= csrf_field() ?><input name="code" placeholder="<?= e($sf->t('wh_code')) ?>" maxlength="40" required><input name="name" placeholder="<?= e($sf->t('wh_name')) ?>" maxlength="160" required><button class="btn primary" name="do" value="add_wh"><?= e($sf->t('add')) ?></button></form></div>
<div class="card"><h3><?= e($sf->t('staff')) ?></h3><p class="muted"><?= e($sf->t('staff_hint')) ?></p>
  <?php foreach ($staff as $s): ?><form method="post" class="row"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$s['user_id'] ?>"><b><?= e($s['name']) ?></b> <span class="muted"><?= e($s['email']) ?></span> <span class="gi-st"><?= e($sf->t('role_' . $s['role'])) ?></span> <?= e($s['wname'] ?? '') ?><button class="btn sm" name="do" value="del_staff" onclick="return confirm('<?= e($sf->t('confirm_remove')) ?>')"><?= e($sf->t('remove')) ?></button></form><?php endforeach; ?>
  <form method="post" class="row"><?= csrf_field() ?><select name="user_id"><?php foreach ($users as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['name']) ?> — <?= e($u['email']) ?></option><?php endforeach; ?></select>
    <select name="role"><option value="operator"><?= e($sf->t('role_operator')) ?></option><option value="office"><?= e($sf->t('role_office')) ?></option></select>
    <select name="warehouse_id"><?php foreach ($whs as $w): ?><option value="<?= (int)$w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><button class="btn primary" name="do" value="add_staff"><?= e($sf->t('add')) ?></button></form></div>
<div class="card"><h3><?= e($sf->t('devices')) ?></h3><p class="muted"><?= e($sf->t('devices_hint')) ?></p>
  <?php if (!$devices): ?><p class="muted"><?= e($sf->t('none')) ?></p><?php endif; ?>
  <?php foreach ($devices as $d): ?><form method="post" class="row"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$d['id'] ?>"><b><?= e($d['name']) ?></b> <span class="muted"><?= e($d['label']) ?> · <code><?= e(substr($d['device_id'], 0, 10)) ?></code> · <?= e((string)$d['last_seen']) ?></span> <span class="gi-st gi-dev-<?= e($d['status']) ?>"><?= e($sf->t('dev_' . $d['status'])) ?></span>
    <?php if ($d['status'] !== 'approved'): ?><button class="btn sm primary" name="do" value="dev_approve"><?= e($sf->t('approve')) ?></button><?php endif; ?><?php if ($d['status'] !== 'revoked'): ?><button class="btn sm" name="do" value="dev_revoke"><?= e($sf->t('revoke')) ?></button><?php endif; ?></form><?php endforeach; ?></div>
